#include <bits/stdc++.h>
using namespace std;

#define ll long long
using vll = vector<ll>;
#define FOR(i, s, n) for (int i = s; i < n; i++)

const ll MOD = 998244353;
const ll MAXN = 2e5;

vll fact(MAXN + 1);
vll invfact(MAXN + 1);

ll power(ll base, ll e){
    ll res = 1;
    base %= MOD;
    while (e > 0){
        if (e % 2)
            res = res * base % MOD;
        base = base * base % MOD;
        e /= 2;
    }
    return res;
}

ll modInverse(ll n){
    return power(n, MOD - 2);
}

void fac(){
    fact[0] = 1;
    for (ll i = 1; i <= MAXN; i++)
        fact[i] = fact[i - 1] * i % MOD;
    
    invfact[MAXN] = modInverse(fact[MAXN]);
    for (ll i = MAXN; i >= 1; i--){
        invfact[i - 1] = invfact[i] * i % MOD;
    }
}

void solve(){
    int n;
    cin >> n;
    vll a(n);
    FOR(i, 0, n)
        cin >> a[i];
    if (n == 1){
        cout << 0 << endl;
        return;
    }
    vll p(n + 1);
    p[0] = 0;
    FOR(i, 0, n){
        p[i + 1] = (p[i] + modInverse(i + 1)) % MOD;
    }
    ll ans = 0;
    FOR(i, 0, n){
        ans = ans + a[i] * ((p[i] + p[n - i - 1]) % MOD) % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
}

int main() {
	// your code goes here
	
	fac();
	
    int t;
    cin >> t;
    while (t--){
        solve();
    }
}
